'use strict';
(()=>{
 const svgBase=PreciseEngine.toSVG,epsBase=PreciseEngine.toEPS;
 const n=v=>String(Math.round(v*1000)/1000),lum=c=>.2126*c.r+.7152*c.g+.0722*c.b;
 function seams(td){if(!td.graph||td.strokeWidth||td.seamFill===false)return [];return td.graph.edges.flatMap(e=>{if(e.left<0||e.right<0)return [];const a=td.palette[td.graph.faces[e.left].color],b=td.palette[td.graph.faces[e.right].color];if(a.a!==255||b.a!==255)return [];return [{segments:e.segments,color:lum(a)<lum(b)?a:b}];});}
 function ps(path){const a=path.segments[0],out=[n(a.x1)+' '+n(a.y1)+' moveto'];for(const s of path.segments){if(s.type==='C')out.push([s.x2,s.y2,s.x3,s.y3,s.x4,s.y4].map(n).join(' ')+' curveto');else if(s.type==='Q')out.push([s.x1+2/3*(s.x2-s.x1),s.y1+2/3*(s.y2-s.y1),s.x3+2/3*(s.x2-s.x3),s.y3+2/3*(s.y2-s.y3),s.x3,s.y3].map(n).join(' ')+' curveto');else out.push(n(s.x2)+' '+n(s.y2)+' lineto');}if(!path.open)out.push('closepath');return out.join('\n');}
 PreciseEngine.toSVG=function(td,width){const svg=svgBase(td,width),edges=seams(td);if(!edges.length)return svg;const doc=new DOMParser().parseFromString(svg,'image/svg+xml'),ns='http://www.w3.org/2000/svg',defs=doc.createElementNS(ns,'defs'),clip=doc.createElementNS(ns,'clipPath');clip.id='seam-coverage';clip.setAttribute('clipPathUnits','userSpaceOnUse');for(const path of doc.querySelectorAll('g[id^="color-"] > path')){const copy=path.cloneNode(true);copy.removeAttribute('fill');copy.setAttribute('clip-rule','evenodd');clip.append(copy);}defs.append(clip);const group=doc.createElementNS(ns,'g');group.setAttribute('data-seam-underlay','true');group.setAttribute('clip-path','url(#seam-coverage)');for(const e of edges){const path=doc.createElementNS(ns,'path');path.setAttribute('d',refineD(e.segments));path.setAttribute('fill','none');path.setAttribute('stroke','rgb('+[e.color.r,e.color.g,e.color.b].join(',')+')');path.setAttribute('stroke-width','.7');path.setAttribute('stroke-linejoin','round');path.setAttribute('stroke-linecap','butt');group.append(path);}doc.documentElement.prepend(defs,group);return new XMLSerializer().serializeToString(doc);};
 PreciseEngine.toEPS=function(td,width){const original=epsBase(td,width),edges=seams(td);if(!edges.length)return original;const lines=['gsave','newpath'];for(const o of PreciseEngine.objects(td))for(const path of o.paths)lines.push(ps(path));lines.push('eoclip','newpath','0.7 setlinewidth','0 setlinecap','1 setlinejoin');for(const e of edges)lines.push([e.color.r/255,e.color.g/255,e.color.b/255].map(n).join(' ')+' setrgbcolor','newpath',ps({segments:e.segments,open:true}),'stroke');lines.push('grestore');const at=original.indexOf(' scale\n');return original.slice(0,at+7)+lines.join('\n')+'\n'+original.slice(at+7);};
 const field=document.createElement('div');field.className='field';field.innerHTML='<label class="toggle-row"><span>Tutup celah antarwarna</span><input id="seamFill" type="checkbox" checked></label><p class="hint">Overlap internal 0,7 px pemrosesan. Untuk garis tipis akibat rendering, bukan lubang geometri besar.</p>';$('protectOutline').closest('.field').after(field);
 $('seamFill').onchange=()=>{if(result){result.td.seamFill=$('seamFill').checked;renderResult();measureDifference();}};
 const previous=renderResult;renderResult=function(){if(result)result.td.seamFill=$('seamFill').checked;return previous();};
})();
